CREATE TABLE "TrainTrackAnalytics" ("id" TEXT NOT NULL,"studentId" TEXT NOT NULL,"assessmentId" TEXT NOT NULL,"gameId" TEXT NOT NULL,"gameResultId" TEXT NOT NULL,"roundsPlayed" INTEGER NOT NULL,"tracksCompleted" INTEGER NOT NULL,"successfulRoutes" INTEGER NOT NULL,"correctRotations" INTEGER NOT NULL,"incorrectRotations" INTEGER NOT NULL,"averageCompletionTime" DOUBLE PRECISION NOT NULL,"highestDifficulty" INTEGER NOT NULL,"logicalAccuracy" DOUBLE PRECISION NOT NULL,"logicalThinkingScore" DOUBLE PRECISION NOT NULL,"causeEffectScore" DOUBLE PRECISION NOT NULL,"completionPercentage" DOUBLE PRECISION NOT NULL,"overallScore" DOUBLE PRECISION NOT NULL,"completionStatus" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "TrainTrackAnalytics_pkey" PRIMARY KEY ("id"));
